Rules.InvariantScript:
Set(varDF_ChangedFieldKey, ThisItem.FieldKey);
Set(varDF_ChangedFieldType, ThisItem.FieldType);
Set(varDF_ChangedValueSlot, "ValueText");
Set(varDF_ChangedValueText, Self.Text);

cmp_DynamicFilters.OnValueChanged()

ForAll(
    Table(
        ParseJSON(
            If(
                IsBlank(Trim(Coalesce(ThisItem.OptionsJson, ""))),
                "[]",
                ThisItem.OptionsJson
            )
        )
    ),
    {Value: Text(Value)}
)

If(
    Lower(Trim(ThisItem.FieldType)) = "choice",
    If(
        IsBlank(
            LookUp(
                cmp_DynamicFilters.Values,
                FieldKey = ThisItem.FieldKey
            ).ValueText
        ),
        Blank(),
        Table(
            {
                Value:
                    LookUp(
                        cmp_DynamicFilters.Values,
                        FieldKey = ThisItem.FieldKey
                    ).ValueText
            }
        )
    ),
    If(
        Lower(Trim(ThisItem.FieldType)) = "multichoice",
        ForAll(
            Table(
                ParseJSON(
                    Coalesce(
                        LookUp(
                            cmp_DynamicFilters.Values,
                            FieldKey = ThisItem.FieldKey
                        ).ValueJson,
                        "[]"
                    )
                )
            ),
            {Value: Text(Value)}
        ),
        Blank()
    )
)

Set(varDF_ChangedFieldKey, ThisItem.FieldKey);
Set(varDF_ChangedFieldType, ThisItem.FieldType);

If(
    Lower(Trim(ThisItem.FieldType)) = "choice",

    Set(varDF_ChangedValueSlot, "ValueText");
    Set(varDF_ChangedValueText, Coalesce(Self.Selected.Value, "")),

    Set(varDF_ChangedValueSlot, "ValueJson");
    Set(
        varDF_ChangedValueJson,
        "[" &
        Concat(
            Self.SelectedItems,
            """" & Substitute(Value, """", "\""") & """",
            ","
        ) &
        "]"
    )
);

cmp_DynamicFilters.OnValueChanged()

Set(varDF_ChangedFieldKey, ThisItem.FieldKey);
Set(varDF_ChangedFieldType, ThisItem.FieldType);
Set(varDF_ChangedValueSlot, "ValueDateFrom");
Set(varDF_ChangedValueDate, Coalesce(Self.SelectedDate, Date(1900,1,1)));

cmp_DynamicFilters.OnValueChanged()

Set(varDF_ChangedFieldKey, ThisItem.FieldKey);
Set(varDF_ChangedFieldType, ThisItem.FieldType);
Set(varDF_ChangedValueSlot, "ValueDateTo");
Set(varDF_ChangedValueDate, Coalesce(Self.SelectedDate, Date(1900,1,1)));

cmp_DynamicFilters.OnValueChanged()

Set(varDF_ChangedFieldKey, ThisItem.FieldKey);
Set(varDF_ChangedFieldType, ThisItem.FieldType);

If(
    ThisItem.FilterMode = "Between",
    Set(varDF_ChangedValueSlot, "ValueNumberFrom");
    Set(varDF_ChangedValueNumber, Coalesce(Value(Self.Value), 0)),

    Set(varDF_ChangedValueSlot, "ValueNumberFrom");
    Set(varDF_ChangedValueNumber, Coalesce(Value(Self.Value), 0));
    cmp_DynamicFilters.OnValueChanged();

    Set(varDF_ChangedValueSlot, "ValueNumberTo");
    Set(varDF_ChangedValueNumber, Coalesce(Value(Self.Value), 0))
);

cmp_DynamicFilters.OnValueChanged()

Set(varDF_ChangedFieldKey, ThisItem.FieldKey);
Set(varDF_ChangedFieldType, ThisItem.FieldType);
Set(varDF_ChangedValueSlot, "ValueNumberTo");
Set(varDF_ChangedValueNumber, Coalesce(Value(Self.Value), 0));

cmp_DynamicFilters.OnValueChanged()

Set(varDF_ChangedFieldKey, ThisItem.FieldKey);
Set(varDF_ChangedFieldType, ThisItem.FieldType);
Set(varDF_ChangedValueSlot, "ValueBool");
Set(varDF_ChangedValueBool, true);

cmp_DynamicFilters.OnValueChanged()

Set(varDF_ChangedFieldKey, ThisItem.FieldKey);
Set(varDF_ChangedFieldType, ThisItem.FieldType);
Set(varDF_ChangedValueSlot, "ValueBool");
Set(varDF_ChangedValueBool, false);

cmp_DynamicFilters.OnValueChanged()

Set(varDF_ChangedFieldKey, "");
Set(varDF_ChangedFieldType, "");
Set(varDF_ChangedValueSlot, "ClearAll");
Set(varDF_ChangedValueText, "");
Set(varDF_ChangedValueNumber, 0);
Set(varDF_ChangedValueDate, DateTime(1900,1,1,0,0,0));
Set(varDF_ChangedValueBool, false);
Set(varDF_ChangedValueJson, "");

cmp_DynamicFilters.OnValueChanged();

cmp_DynamicFilters.OnClear()

Set(varDF_ChangedFieldKey, "");
Set(varDF_ChangedFieldType, "");
Set(varDF_ChangedValueSlot, "");
Set(varDF_ChangedValueText, "");
Set(varDF_ChangedValueNumber, 0);
Set(varDF_ChangedValueDate, DateTime(1900,1,1,0,0,0));
Set(varDF_ChangedValueBool, false);
Set(varDF_ChangedValueJson, "")
